      const box = labelTextBox({ node: node, geo: geo, fontSize: fontSize })
      // 与渲染同一处断行：maxWidth 就是那一个 labelTextWidth（nowrap = 一行到底）。
      const lines = labelWraps(node) ? wrapLabel(label, box.w, fontSize) : label.split('\n')
