        if (isHiddenCell(hidden, n)) continue
        const geo = nodeBoxOf(n)
        if (geo.x < minX) minX = geo.x
        if (geo.y < minY) minY = geo.y
        if (geo.x + geo.w > maxX) maxX = geo.x + geo.w
        if (geo.y + geo.h > maxY) maxY = geo.y + geo.h
