        const provider = saved.imagegenProvider === 'openai' ? 'openai' : 'comfyui'
        const body = { action: 'imagegen-status', sessionId, provider }
        if (provider === 'comfyui') body.comfyUrl = String(saved.imagegenComfyUrl || '').trim()
